(function() {
    'use strict';

    class SaboresAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'La Decision del Lanzamiento';
            this.version = '1.1.0';
            this.FORMULAS = [
                { id: 1, vc: 2.80, modifier: 1.00 },
                { id: 2, vc: 3.10, modifier: 0.90 }
            ];
            this.PACKAGING = [
                { id: 1, cost: 0.15, ceiling: 6.50 },
                { id: 2, cost: 0.28, ceiling: 8.50 },
                { id: 3, cost: 0.55, ceiling: 9.50 }
            ];
            this.PRICES = [
                { id: 1, price: 4.50, demandMult: 1.60 },
                { id: 2, price: 6.50, demandMult: 1.00 },
                { id: 3, price: 8.90, demandMult: 0.55 }
            ];
            this.CHANNELS = [
                { id: 1, reach: 28000, convRate: 0.01, cost: 8000 },
                { id: 2, reach: 3600, convRate: 0.20, cost: 12000 },
                { id: 3, reach: 18000, convRate: 0.05, cost: 15000 }
            ];
            this.PRICE_PROMO = [
                [0.22, 0.33, 0.12],
                [0.25, 0.28, 0.30],
                [0.08, 0.18, 0.33]
            ];
            this.PRODUCT_PROMO = [
                [0.25, 0.34, 0.20],
                [0.12, 0.22, 0.34]
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    budget: 18000,
                    productionRun: 2000,
                    formula: 0,
                    packaging: 0,
                    priceTier: 0,
                    channel: 0,
                    baseVC: 0,
                    packagingCost: 0,
                    totalUnitCost: 0,
                    priceCeiling: 0,
                    price: 0,
                    demandMultiplier: 0,
                    unitMargin: 0,
                    channelCost: 0,
                    unitsSold: 0,
                    revenue: 0,
                    grossMargin: 0,
                    grossMarginPct: 0,
                    revenueAttainment: 0,
                    coherenceScore: 0,
                    channelEfficiency: 0,
                    totalScore: 0,
                    revenueScore: 0,
                    marginScore: 0,
                    efficiencyScore: 0,
                    coherencePoints: 0,
                    revenueHistory: [],
                    phaseHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    formula: 1,
                    packaging: 1,
                    priceTier: 2,
                    channel: 1
                };
            }
            this._updateBriefing(state);
            var self = this;
            setTimeout(function() { self._setupListeners(); }, 200);
        }

        _setupListeners() {
            var self = this;
            var formulaRadios = document.querySelectorAll('input[name="formula"]');
            formulaRadios.forEach(function(r) {
                r.addEventListener('change', function() { self._updateFormulaPreview(); });
            });
            var pkgRadios = document.querySelectorAll('input[name="packaging"]');
            pkgRadios.forEach(function(r) {
                r.addEventListener('change', function() { self._updatePackagingPreview(); });
            });
            var priceRadios = document.querySelectorAll('input[name="priceTier"]');
            priceRadios.forEach(function(r) {
                r.addEventListener('change', function() { self._updatePricePreview(); });
            });
            var channelRadios = document.querySelectorAll('input[name="channel"]');
            channelRadios.forEach(function(r) {
                r.addEventListener('change', function() { self._updateChannelPreview(); });
            });
            this._updateFormulaPreview();
            this._updatePackagingPreview();
        }

        _t(key) {
            if (window.mySimulation && window.mySimulation.t) {
                return window.mySimulation.t(key);
            }
            return key;
        }

        _updateFormulaPreview() {
            var el = document.getElementById('formulaPreview');
            if (!el) return;
            var sel = document.querySelector('input[name="formula"]:checked');
            if (!sel) return;
            var val = parseInt(sel.value);
            el.innerHTML = val === 1 ? this._t('preview_plant') : this._t('preview_whey');
        }

        _updatePackagingPreview() {
            var el = document.getElementById('packagingPreview');
            if (!el) return;
            var sel = document.querySelector('input[name="packaging"]:checked');
            if (!sel) return;
            var val = parseInt(sel.value);
            var keys = ['preview_eco', 'preview_foil', 'preview_sleeve'];
            el.innerHTML = this._t(keys[val - 1]);
        }

        _updatePricePreview() {
            var signalEl = document.getElementById('priceSignal');
            var marginEl = document.getElementById('marginCalculator');
            var warnEl = document.getElementById('coherenceWarning');
            var sel = document.querySelector('input[name="priceTier"]:checked');
            if (!sel) return;
            var val = parseInt(sel.value);
            var ds = window.mySimulation ? window.mySimulation.state.domainState : null;
            if (signalEl) {
                var signalKeys = ['signal_economy', 'signal_standard', 'signal_premium'];
                signalEl.innerHTML = this._t(signalKeys[val - 1]);
            }
            if (marginEl && ds && ds.totalUnitCost > 0) {
                var prices = [4.50, 6.50, 8.90];
                var price = prices[val - 1];
                var margin = price - ds.totalUnitCost;
                var avgChannelCost = 12000;
                var breakEven = margin > 0 ? Math.ceil(avgChannelCost / margin) : 9999;
                var maxMargin = margin * ds.productionRun;
                marginEl.innerHTML = this._t('margin_info') + ': S/. ' + margin.toFixed(2) +
                    '<br>' + this._t('breakeven_info') + ': ' + breakEven.toLocaleString() + ' ' + this._t('units_text') +
                    '<br>' + this._t('max_margin_info') + ': S/. ' + maxMargin.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2});
            }
            if (warnEl && ds) {
                var prices = [4.50, 6.50, 8.90];
                var price = prices[val - 1];
                if (ds.priceCeiling > 0 && price > ds.priceCeiling + 1.00) {
                    warnEl.style.display = 'block';
                    warnEl.innerHTML = this._t('coherence_warning_text');
                } else {
                    warnEl.style.display = 'none';
                }
            }
        }

        _updateChannelPreview() {
            var detailEl = document.getElementById('channelDetail');
            var surplusEl = document.getElementById('budgetSurplus');
            var sel = document.querySelector('input[name="channel"]:checked');
            if (!sel) return;
            var val = parseInt(sel.value);
            if (detailEl) {
                var detailKeys = ['detail_social', 'detail_campus', 'detail_influencer'];
                detailEl.innerHTML = this._t(detailKeys[val - 1]);
            }
            if (surplusEl) {
                var costs = [8000, 12000, 15000];
                var surplus = 18000 - costs[val - 1];
                var boost = ((surplus / 1000) * 4).toFixed(0);
                surplusEl.innerHTML = this._t('surplus_label') + ': S/. ' + surplus.toLocaleString() +
                    '<br>' + this._t('contingency_label') + ': +' + boost + '% ' + this._t('reach_text');
            }
        }

        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var productPanel = document.getElementById('productPanel');
            var pricePanel = document.getElementById('pricePanel');
            var promoPanel = document.getElementById('promoPanel');
            var briefEl = document.getElementById('briefingText');
            if (productPanel) productPanel.style.display = period === 1 ? 'block' : 'none';
            if (pricePanel) pricePanel.style.display = period === 2 ? 'block' : 'none';
            if (promoPanel) promoPanel.style.display = period === 3 ? 'block' : 'none';
            if (briefEl) {
                var keys = ['briefing_product', 'briefing_price', 'briefing_promo'];
                var idx = Math.min(period - 1, 2);
                briefEl.innerHTML = this._t(keys[idx]);
            }
            if (period === 2) {
                var self = this;
                setTimeout(function() { self._updatePricePreview(); }, 150);
            }
            if (period === 3) {
                var self = this;
                setTimeout(function() { self._updateChannelPreview(); }, 150);
            }
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);
            var state = window.mySimulation.state;
            var period = state.currentPeriod;
            if (period === 1) {
                var f = document.querySelector('input[name="formula"]:checked');
                var p = document.querySelector('input[name="packaging"]:checked');
                if (!f || !p) {
                    window.mySimulation.uiManager.showNotification(this._t('select_all_warning'), 'warning');
                    return false;
                }
                decisions.formula = parseInt(f.value);
                decisions.packaging = parseInt(p.value);
            } else if (period === 2) {
                var pt = document.querySelector('input[name="priceTier"]:checked');
                if (!pt) {
                    window.mySimulation.uiManager.showNotification(this._t('select_price_warning'), 'warning');
                    return false;
                }
                decisions.priceTier = parseInt(pt.value);
            } else if (period === 3) {
                var ch = document.querySelector('input[name="channel"]:checked');
                if (!ch) {
                    window.mySimulation.uiManager.showNotification(this._t('select_channel_warning'), 'warning');
                    return false;
                }
                decisions.channel = parseInt(ch.value);
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var results = { period: period };
            if (period === 1) {
                var formulaData = this.FORMULAS[d.formula - 1];
                var pkgData = this.PACKAGING[d.packaging - 1];
                ds.formula = d.formula;
                ds.packaging = d.packaging;
                ds.baseVC = formulaData.vc;
                ds.packagingCost = pkgData.cost;
                ds.totalUnitCost = Math.round((formulaData.vc + pkgData.cost) * 100) / 100;
                ds.priceCeiling = pkgData.ceiling;
                results.phaseName = this._t('phase_product');
                results.decisionSummary = this._t('name_' + (d.formula === 1 ? 'plant' : 'whey')) + ' + ' + this._t('name_pkg_' + d.packaging);
                results.impactSummary = 'S/. ' + ds.totalUnitCost.toFixed(2) + '/ud';
                results.unitCost = ds.totalUnitCost;
                ds.revenueHistory.push(0);
                ds.phaseHistory.push('product');
            } else if (period === 2) {
                var priceData = this.PRICES[d.priceTier - 1];
                ds.priceTier = d.priceTier;
                ds.price = priceData.price;
                ds.demandMultiplier = priceData.demandMult;
                ds.unitMargin = Math.round((ds.price - ds.totalUnitCost) * 100) / 100;
                results.phaseName = this._t('phase_price');
                results.decisionSummary = this._t('name_tier_' + d.priceTier);
                results.impactSummary = this._t('margin_info') + ': S/. ' + ds.unitMargin.toFixed(2);
                results.price = ds.price;
                results.unitMargin = ds.unitMargin;
                ds.revenueHistory.push(Math.round(ds.productionRun * ds.price * 100) / 100);
                ds.phaseHistory.push('price');
            } else if (period === 3) {
                var channelData = this.CHANNELS[d.channel - 1];
                ds.channel = d.channel;
                ds.channelCost = channelData.cost;
                var budgetSurplus = ds.budget - channelData.cost;
                var contingencyBoost = (budgetSurplus / 1000) * 0.04;
                var adjustedReach = channelData.reach * (1 + contingencyBoost);
                var baseBuyers = adjustedReach * channelData.convRate;
                var formulaModifier = this.FORMULAS[ds.formula - 1].modifier;
                var adjustedBuyers = baseBuyers * ds.demandMultiplier * formulaModifier;
                if (ds.price <= ds.priceCeiling) {
                    adjustedBuyers *= 1.10;
                } else if (ds.price > ds.priceCeiling + 1.00) {
                    adjustedBuyers *= 0.80;
                }
                ds.unitsSold = Math.min(Math.round(adjustedBuyers), ds.productionRun);
                ds.revenue = Math.round(ds.unitsSold * ds.price * 100) / 100;
                var totalVC = ds.unitsSold * ds.totalUnitCost;
                ds.grossMargin = Math.round((ds.revenue - totalVC) * 100) / 100;
                ds.grossMarginPct = ds.revenue > 0 ? ds.grossMargin / ds.revenue : 0;
                var maxRevenue = ds.productionRun * ds.price;
                ds.revenueAttainment = maxRevenue > 0 ? ds.revenue / maxRevenue : 0;
                var ppCoherence = 0.33;
                if (ds.price > ds.priceCeiling + 1.00) { ppCoherence = 0.08; }
                else if (ds.price > ds.priceCeiling) { ppCoherence = 0.20; }
                var pricePromo = this.PRICE_PROMO[ds.priceTier - 1][d.channel - 1];
                var productPromo = this.PRODUCT_PROMO[ds.formula - 1][d.channel - 1];
                ds.coherenceScore = ppCoherence + pricePromo + productPromo;
                ds.channelEfficiency = ds.channelCost > 0 ? ds.grossMargin / (ds.channelCost / 1000) : 0;
                var ra = ds.revenueAttainment * 100;
                var revScore = 2;
                if (ra >= 90) { revScore = 30; }
                else if (ra >= 75) { revScore = 22; }
                else if (ra >= 60) { revScore = 15; }
                else if (ra >= 45) { revScore = 8; }
                var marginBenchmark = 0.45;
                var marginScore = Math.min(25, Math.max(0, Math.round((ds.grossMarginPct / marginBenchmark) * 25)));
                var effScore = Math.min(25, Math.max(0, Math.round((ds.channelEfficiency / 300) * 25)));
                var cohScore = Math.min(20, Math.round(ds.coherenceScore * 20));
                ds.revenueScore = revScore;
                ds.marginScore = marginScore;
                ds.efficiencyScore = effScore;
                ds.coherencePoints = cohScore;
                ds.totalScore = revScore + marginScore + effScore + cohScore;
                results.phaseName = this._t('phase_promo');
                results.decisionSummary = this._t('name_ch_' + d.channel);
                results.impactSummary = ds.unitsSold + ' uds — S/. ' + ds.revenue.toLocaleString();
                results.unitsSold = ds.unitsSold;
                results.revenue = ds.revenue;
                results.grossMargin = ds.grossMargin;
                results.totalScore = ds.totalScore;
                ds.revenueHistory.push(ds.revenue);
                ds.phaseHistory.push('promo');
            }
            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);
            return results;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('budgetDisplay', 'domainState.budget',
                function(v) { return 'S/. ' + v.toLocaleString(); });
            uiManager.bind('productionDisplay', 'domainState.productionRun',
                function(v) { return v.toLocaleString() + ' uds'; });
            uiManager.bind('unitCostDisplay', 'domainState.totalUnitCost',
                function(v) { return v > 0 ? 'S/. ' + v.toFixed(2) : '--'; });
            uiManager.bind('unitMarginDisplay', 'domainState.unitMargin',
                function(v) { return v > 0 ? 'S/. ' + v.toFixed(2) : '--'; });
        }

        getChartConfig() {
            return {
                projectionChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'S/.',
                            data: [],
                            backgroundColor: [
                                'rgba(52,152,219,0.6)',
                                'rgba(46,204,113,0.6)',
                                'rgba(231,76,60,0.6)'
                            ],
                            borderColor: [
                                '#3498db',
                                '#2ecc71',
                                '#e74c3c'
                            ],
                            borderWidth: 2,
                            borderRadius: 8
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: {
                                display: true,
                                text: this._t('chart_title')
                            }
                        },
                        scales: {
                            y: { beginAtZero: true }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var phaseLabels = [];
            var phaseKeys = { product: this._t('phase_product'), price: this._t('phase_price'), promo: this._t('phase_promo') };
            for (var i = 0; i < state.domainState.phaseHistory.length; i++) {
                var k = state.domainState.phaseHistory[i];
                phaseLabels.push(phaseKeys[k] || k);
            }
            return {
                projectionChart: {
                    labels: phaseLabels,
                    datasets: [{ data: state.domainState.revenueHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastResult = history[history.length - 1];
            if (!lastResult || !lastResult.results) return {};
            var ds = window.mySimulation ? window.mySimulation.state.domainState : {};
            var totalScore = ds.totalScore || 0;
            var performance = 'Needs Review';
            var bandKey = 'band_needs_review';
            if (totalScore >= 75) { performance = 'Excellent'; bandKey = 'band_excellent'; }
            else if (totalScore >= 62) { performance = 'Proficient'; bandKey = 'band_proficient'; }
            else if (totalScore >= 48) { performance = 'Developing'; bandKey = 'band_developing'; }
            var insights = [];
            insights.push(this._t('kpi_revenue') + ': ' + (ds.revenueScore || 0) + '/30');
            insights.push(this._t('kpi_margin') + ': ' + (ds.marginScore || 0) + '/25');
            insights.push(this._t('kpi_efficiency') + ': ' + (ds.efficiencyScore || 0) + '/25');
            insights.push(this._t('kpi_coherence') + ': ' + (ds.coherencePoints || 0) + '/20');
            return {
                totalScore: totalScore,
                performance: performance,
                bandLabel: this._t(bandKey),
                unitsSold: ds.unitsSold || 0,
                revenue: ds.revenue || 0,
                grossMargin: ds.grossMargin || 0,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var ds = state.domainState;
            if (results.totalScore !== undefined) {
                if (ds.coherenceScore < 0.50) return this._t('hint_coherence_low');
                if (ds.grossMarginPct < 0.30) return this._t('hint_margin_low');
                return this._t('hint_good');
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.phaseName', label: 'Fase', i18nKey: 'col_phase' },
                { key: 'results.decisionSummary', label: 'Decisión', i18nKey: 'col_decision' },
                { key: 'results.impactSummary', label: 'Impacto', i18nKey: 'col_impact' }
            ];
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title:                  `The Launch Decision`,
                    subtitle:               `Sabores del Valle S.A. — Barra Andina Sport`,
